"""Hidden behavioral tests for cmark: spec_latex. Generated by pbkit from the gold binary."""


def test_spec_003_latex(run):
    """spec example 3 (tabs) rendered as latex"""
    r = run(args=['-t', 'latex'], stdin=b'    a\ta\n    \xe1\xbd\x90\ta\n')
    assert r.stdout == b'\\begin{verbatim}\na\ta\n\xe1\xbd\x90\ta\n\\end{verbatim}\n'
    assert r.stderr == b''
    assert r.returncode == 0


